                  <svg width="12" height="12" viewBox="0 0 24 24" fill="#fff"><path d="M12 23c-4.97 0-9-3.58-9-8 0-3.07 2.25-6.51 4.06-8.25.28-.27.72-.09.75.3.18 2.16 1.35 3.58 2.44 4.2.14.08.31-.02.3-.18-.15-2.2.6-4.8 2.7-7.57.2-.26.6-.22.74.08C15.68 7.4 17 10.54 17 13c0 .52-.05 1.02-.14 1.5-.04.21.17.38.35.24C18.34 13.88 19 12.62 19 11c0-.09.12-.14.18-.07C20.93 12.85 21 15 21 15c0 4.42-4.03 8-9 8z"/></svg>
